record Shape(p: path, n: number)
const P: path = segment(start: (0, 0), end: (3, 4))
const A: Shape = Shape(p: @P, n: 19)
const Values: Shape[] = [@A]
const Mapped: Shape[] = for item in @Values { Shape(p: @item.p, n: @item.n + 2) }
const Chosen: Shape = @Mapped[0]
const Result: path = @Chosen.p
const L: number = @Result.length
const N: number = @Chosen.n

