record Box(n: number)
module Make(n: number) {
 const Values: Box?[] = [none, Box(n: @n)]
 export const Chosen: Box = match @Values[1] { none => Box(n: 1 / 0) some held => Box(n: @held.n + 2) }
}
instance One = Make(n: 19)
instance Two = Make(n: 43)
const X: number = @One::Chosen.n
const Y: number = @Two::Chosen.n

