record Shape(p: path, n: number)
module Make(x: number) {
 const P: path = segment(start: (0, 0), end: (@x, 0))
const A: Shape = Shape(p: @P, n: 19)
const Values: Shape[] = [@A]
const Mapped: Shape[] = for item in @Values { @item }
const Chosen: Shape = @Mapped[0]
const Result: path = @Chosen.p
export const L: number = @Result.length
export const N: number = @Chosen.n
}
instance One = Make(x: 11)
instance Two = Make(x: 29)
const X: number = @One::L
const Y: number = @Two::L

